370.0 680.0 380.0 770.0 460.0"}></path></g></svg></div><div className={"container"}><nav aria-label={"Breadcrumb"} data-anim={"fade"}><ol className={"breadcrumb custom-ph-crumb"}><li className={"breadcrumb-item"}><a href={"#page=demo-consulting-3"}>{"Home"}</a></li><li className={"breadcrumb-item"}><a href={"#page=demo-consulting-3-blog"}>{"Blog"}</a></li><li className={"breadcrumb-item"} aria-current={"page"}>{"What breaks at 250 people"}</li></ol></nav><div className={"grid gap-8 mt-[clamp(2rem,1.5rem+2vw,3.5rem)] lg:grid-cols-12 lg:items-end"}><div className={"lg:col-span-8"}><p className={"eyebrow custom-eyebrow m-0"} data-anim={"fade-up"}>{"Organisation Design · 7 min read"}</p><h1 id={"c3p-page-title"} className={"custom-ph-title mt-6 mb-0"} data-anim={"fade-up"} data-anim-delay={"80"}>{"What breaks at 250 people, "}<span className={"custom-ph-soft"}>{"and what to fix first."}</span></h1></div><p className={"m-0 text-lg leading-relaxed custom-ph-lead lg:col-span-4"} data-anim={"fade-up"} data-anim-delay={"160"}>{"By Tessa Halloran, Partner · October 14, 2026"}</p></div><img className={"custom-ph-photo"} src={"https://draftmango.com/draftmango/assets/media/placeholder/1200x900.svg"} alt={"A founder studying a printed organisation chart at a long table"} width={"1600"} height={"1200"} fetchPriority={"high"} decoding={"async"} data-anim={"fade-up"} data-anim-delay={"200"} /></div></section><article id={"c3p-article"} className={"py-(--section-space)"}><div className={"container"}><div className={"article-body article-body--flush custom-article mx-auto max-w-[46rem]"}><p className={"text-xl leading-relaxed"}>{"Somewhere between 200 and 300 people, almost every company we work with hits the same wall. The founders stop knowing everyone by name, decisions start to queue at the top, and the informal ways of working that made the company fast begin to slow it down."}</p><h2>{"1. Decision rights before org charts"}</h2><p>{"The first instinct is to redraw the org chart. Resist it for a week. Write down the twenty decisions that come up every month, from hiring to pricing exceptions, and agree who makes each one. Half of the friction disappears before a single box moves."}</p><h2>{"2. Spans of seven, not fourteen"}</h2><p>{"At 250 people we often find managers with fourteen or more direct reports, most of them promoted from the best individual contributors. Nobody can coach fourteen people. Aim for six to eight, and add a layer only where it buys real coaching time."}</p><blockquote><p>{"“The org chart is the last thing to change, not the first. Decide who decides, then draw the boxes.”"}</p></blockquote><h2>{"3. Train the first line of managers"}</h2><p>{"New structure fails without managers who can run it. Before the announcement, give every first-line manager the basics: a weekly one-to-one, clear goals and the confidence to give feedback early."}</p><h2>{"4. A people team that fits the size"}</h2><p>{"A company of 250 needs more than one generalist HR person. Usually that means an HR business partner for the managers, a talent lead for hiring, and simple, written policies that people can find."}</p><p>{"None of this is glamorous. All of it works, and in our experience it buys a company another two or three years of growth before the next wall."}</p></div><div className={"custom-author mx-auto mt-14 max-w-[46rem] flex flex-wrap items-center gap-5 p-6 rounded-(--radius-lg) bg-soft"} data-anim={"fade-up"}><img className={"size-16 rounded-full object-cover"} src={"https://draftmango.com/draftmango/assets/media/placeholder/240x240.svg"} alt={""} width={"240"} height={"240"} loading={"lazy"} decoding={"async"} /><div className={"flex-1 min-w-[14rem]"}><p className={"m-0 font-heading text-[1.125rem] font-bold"}>{"Tessa Halloran"}</p><p className={"mt-1 mb-0 text-soft"}>{"Partner, Organisation Design. Fifteen years redesigning companies from 100 to 5,000 people."}</p></div><a href={"#page=demo-consulting-3-team"} className={"btn btn-outline-secondary"}>{"Meet the Team"}</a></div></div></article><section id={"c3p-blog"} className={"relative isolate overflow-clip py-(--section-space) bg-soft"} aria-labelledby={"c3p-blog-title"}><div className={"custom-lines"} aria-hidden={"true"}><svg className={"custom-lines-start"} viewBox={"0 0 600 800"} fill={"none"} focusable={"false"}><defs><linearGradient id={"c3p-blog-lines-start-fade"} gradientUnits={"userSpaceOnUse"} x1={"0"} y1={"80"} x2={"320"} y2={"800"}><stop offset={"0.3"} stopColor={"currentColor"}></stop><stop offset={"1"} stopColor={"currentColor"} stopOpacity={"0"}></stop></linearGradient></defs><g stroke={"url(#c3p-blog-lines-start-fade)"}><path d={"M-10.0 40.0C140.0 60.0 200.0 200.0 240.0 320.0C280.0 440.0 300.0 560.0 420.0 810.0"}></path><path d={"M-10.0 45.2C138.8 65.2 198.4 204.4 238.0 324.0C277.6 443.6 297.4 562.8 416.4 810.0"}></path><path d={"M-10.0 52.3C137.2 72.3 196.2 210.4 235.3 329.4C274.3 448.5 293.9 566.6 411.5 810.0"}></path><path d={"M-10.0 60.4C135.3 80.4 193.7 217.2 232.2 335.7C270.6 454.1 289.8 571.0 405.9 810.0"}></path><path d={"M-10.0 69.2C133.3 89.2 191.0 224.7 228.8 342.5C266.5 460.2 285.4 575.7 399.8 810.0"}></path><path d={"M-10.0 78.6C131.1 98.6 188.1 232.7 225.2 349.7C262.2 466.7 280.7 580.8 393.3 810.0"}></path><path d={"M-10.0 88.5C128.8 108.5 185.1 241.0 221.4 357.3C257.6 473.6 275.8 586.1 386.4 810.0"}></path><path d={"M-10.0 98.8C126.4 118.8 181.9 249.7 217.4 365.2C252.9 480.7 270.6 591.6 379.3 810.0"}></path><path d={"M-10.0 109.5C124.0 129.5 178.6 258.8 213.3 373.4C247.9 488.1 265.3 597.4 371.9 810.0"}></path><path d={"M-10.0 120.5C121.4 140.5 175.2 268.1 209.1 381.9C242.9 495.7 259.8 603.3 364.3 810.0"}></path><path d={"M-10.0 131.8C118.8 151.8 171.8 277.7 204.7 390.6C237.6 503.5 254.1 609.4 356.5 810.0"}></path><path d={"M-10.0 143.4C116.1 163.4 168.2 287.5 200.2 399.5C232.3 511.6 248.3 615.7 348.4 810.0"}></path><path d={"M-10.0 155.3C113.4 175.3 164.5 297.6 195.7 408.7C226.8 519.8 242.4 622.1 340.2 810.0"}